static void require(bool v,const char* message){if(!v)throw std::runtime_error(message);}
template<class F>static void rejects(F&& fn){bool rejected=false;try{fn();}catch(const std::exception&){rejected=true;}require(rejected,"Invalid bokeh input accepted");}
template<class T>static std::vector<T> read(const fs::path& folder,const std::string& name){require(fs::path(name).filename()==fs::path(name),"Invalid bokeh fixture filename");const auto file=folder/name;const auto size=fs::file_size(file);require(size<=16*1024*1024&&size%sizeof(T)==0,"Invalid bokeh fixture size");std::vector<T> values(size/sizeof(T));std::ifstream in(file,std::ios::binary);in.read(reinterpret_cast<char*>(values.data()),std::streamsize(size));require(bool(in),"Cannot read bokeh fixture");return values;}
